    /**** @subsection RTC Field Access Definitions ****/

    static const access_t RTC_RTC_TR_PM_ACCESS           = ACCESS_READ_WRITE;   /** @brief AM/PM notation */
    static const access_t RTC_RTC_DR_YT_ACCESS           = ACCESS_READ_WRITE;   /** @brief Year tens in BCD format */
    static const access_t RTC_RTC_CR_ITSE_ACCESS         = ACCESS_READ_WRITE;   /** @brief Timestamp on internal event enable */
    static const access_t RTC_RTC_ISR_ITSF_ACCESS        = ACCESS_READ_WRITE;   /** @brief Internal ttime-stamp flag */
    static const access_t RTC_RTC_PRER_PREDIV_A_ACCESS   = ACCESS_READ_WRITE;   /** @brief Asynchronous prescaler factor this is the asynchronous division factor: ck_apre frequency = RTCCLK frequency/(prediv_a+1) */
    static const access_t RTC_RTC_WUTR_WUT_ACCESS        = ACCESS_READ_WRITE;   /** @brief Wakeup auto-reload value bits when the wakeup timer is enabled (WUTE set to 1), the WUTF flag is set every (WUT[15:0] + 1) ck_wut cycles. The ck_wut period is selected through WUCKSEL[2:0] bits of the RTC_CR register when WUCKSEL[2] = 1, the wakeup timer becomes 17-bits and WUCKSEL[1] effectively becomes WUT[16] the most-significant bit to be reloaded into the timer. The first assertion of WUTF occurs (WUT+1) ck_wut cycles after WUTE is set. Setting WUT[15:0] to 0x0000 with WUCKSEL[2:0] =011 (RTCCLK/2) is forbidden. */
    static const access_t RTC_RTC_ALRMAR_WDSEL_ACCESS    = ACCESS_READ_WRITE;   /** @brief Week day selection */
    static const access_t RTC_RTC_ALRMBR_WDSEL_ACCESS    = ACCESS_READ_WRITE;   /** @brief Week day selection */
    static const access_t RTC_RTC_WPR_KEY_ACCESS         = ACCESS_WRITE_ONLY;   /** @brief Write protection key this byte is written by software. Reading this byte always returns 0x00. Refer to RTC register write protection for a description of how to unlock RTC register write protection. */
    static const access_t RTC_RTC_SSR_SS_ACCESS          = ACCESS_READ_ONLY;    /** @brief Sub second value SS[15:0] is the value in the synchronous prescaler counter. The fraction of a second is given by the formula below: second fraction = (PREDIV_S - SS) / (PREDIV_S + 1) note: SS can be larger than PREDIV_S only after a shift operation. In that case, the correct time/date is one second less than as indicated by RTC_TR/RTC_DR. */
    static const access_t RTC_RTC_SHIFTR_ADD1S_ACCESS    = ACCESS_WRITE_ONLY;   /** @brief Add one second this bit is write only and is always read as zero. Writing to this bit has no effect when a shift operation is pending (when SHPF=1, in RTC_ISR). This function is intended to be used with SUBFS (see description below) in order to effectively add a fraction of a second to the clock in an atomic operation. */
    static const access_t RTC_RTC_TSTR_PM_ACCESS         = ACCESS_READ_ONLY;    /** @brief AM/PM notation */
    static const access_t RTC_RTC_TSDR_WDU_ACCESS        = ACCESS_READ_ONLY;    /** @brief Week day units */
    static const access_t RTC_RTC_TSSSR_SS_ACCESS        = ACCESS_READ_ONLY;    /** @brief Sub second value SS[15:0] is the value of the synchronous prescaler counter when the timestamp event occurred. */
    static const access_t RTC_RTC_CALR_CALP_ACCESS       = ACCESS_READ_WRITE;   /** @brief Increase frequency of RTC by 488.5 ppm this feature is intended to be used in conjunction with CALM, which lowers the frequency of the calendar with a fine resolution. If the input frequency is 32768 hz, the number of RTCCLK pulses added during a 32-second window is calculated as follows: (512 * CALP) - CALM. Refer to section24.3.12: RTC smooth digital calibration. */
    static const access_t RTC_RTC_ALRMASSR_MASKSS_ACCESS = ACCESS_READ_WRITE;   /** @brief Mask the most-significant bits starting at this bit ... The overflow bits of the synchronous counter (bits 15) is never compared. This bit can be different from 0 only after a shift operation. */
    static const access_t RTC_RTC_ALRMBSSR_MASKSS_ACCESS = ACCESS_READ_WRITE;   /** @brief Mask the most-significant bits starting at this bit ... The overflow bits of the synchronous counter (bits 15) is never compared. This bit can be different from 0 only after a shift operation. */
    static const access_t RTC_RTC_OR_RTC_OUT_RMP_ACCESS  = ACCESS_READ_WRITE;   /** @brief RTC_OUT remap */

    static const access_t RTC_RTC_TAMPCR_TAMPzMF_ACCESS[4] = {
      [1] = ACCESS_READ_WRITE,  /** @brief Tamper 1 mask flag */
      [2] = ACCESS_READ_WRITE,  /** @brief Tamper 2 mask flag */
      [3] = ACCESS_READ_WRITE   /** @brief Tamper 3 mask flag */
    };

